def rle_encode(s):
    """Run-length encode a string: "aaabcc" -> [("a", 3), ("b", 1), ("c", 2)]."""
    if not s:
        return []
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append((s[i], j - i))
        i = j
    return out

