import unittest
from report import iso_date


class TestIsoDate(unittest.TestCase):
    def test_normal_format(self):
        """Test normal date conversion."""
        self.assertEqual(iso_date("2024/05/03"), "2024-05-03")

    def test_scrambled_format(self):
        """Test scrambled date conversion (bank export format)."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")

    def test_leading_zeros(self):
        """Test that leading zeros are handled correctly in various positions."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")
        self.assertEqual(iso_date("05/05/2024"), "2024-05-05")
        self.assertEqual(iso_date("03/05/2024"), "2024-03-05")

    def test_single_digit_values(self):
        """Test that single digit month/day values are zero-padded."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")

    def test_edge_case_zero_padded_year(self):
        """Test year with leading zeros (though unlikely in practice)."""
        self.assertEqual(iso_date("05/03/0204"), "0204-05-03")

    def test_edge_case_zero_padded_month(self):
        """Test month with leading zeros."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")

    def test_edge_case_zero_padded_day(self):
        """Test day with leading zeros."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")

    def test_mixed_padded_values(self):
        """Test mixed padded and non-padded values."""
        self.assertEqual(iso_date("05/03/2024"), "2024-05-03")
        self.assertEqual(iso_date("5/3/2024"), "2024-5-3")

