import unittest
from worker import shipping_order


class TestShippingOrder(unittest.TestCase):
    def test_empty_orders(self):
        """Test with no orders."""
        self.assertEqual(shipping_order([]), [])

    def test_single_order(self):
        """Test with a single order."""
        self.assertEqual(shipping_order(['A']), ['A'])

    def test_two_orders_first_come_first_served(self):
        """Test with two orders: first should ship first."""
        self.assertEqual(shipping_order(['A', 'B']), ['A', 'B'])

    def test_three_orders(self):
        """Test with three orders: A, B, C should ship in order A, B, C."""
        self.assertEqual(shipping_order(['A', 'B', 'C']), ['A', 'B', 'C'])

    def test_four_orders(self):
        """Test with four orders: A, B, C, D should ship in order A, B, C, D."""
        self.assertEqual(shipping_order(['A', 'B', 'C', 'D']), ['A', 'B', 'C', 'D'])

    def test_five_orders(self):
        """Test with five orders: A, B, C, D, E should ship in order A, B, C, D, E."""
        self.assertEqual(shipping_order(['A', 'B', 'C', 'D', 'E']), ['A', 'B', 'C', 'D', 'E'])

    def test_reverse_behavior_check(self):
        """Ensure that the shipping order is first come, first served (not reversed).
        The bug caused reverse order; this test verifies the fix.
        """
        # With the bug, this would have been ['C', 'B', 'A']
        # With the fix, it should be ['A', 'B', 'C']
        self.assertEqual(shipping_order(['A', 'B', 'C']), ['A', 'B', 'C'])


if __name__ == '__main__':
    unittest.main()

