from unittest.mock import patch, MagicMock

# We need to test alerts.py, but sensors.py is unavailable.
# We will mock sensors.read to simulate sensor readings.

import alerts


class TestAlertsTooHot(unittest.TestCase):

    @patch('alerts.read')
    def test_returns_true_when_warm_reading_exceeds_threshold(self, mock_read):
        """Test that too_hot returns True when sensor reading > 30°C."""
        mock_read.return_value = 31.0  # 31 degrees Celsius is > 30
        self.assertTrue(alerts.too_hot("test_sensor"))
        mock_read.assert_called_once_with("test_sensor")

    @patch('alerts.read')
    def test_returns_false_when_warm_reading_equals_threshold(self, mock_read):
        """Test that too_hot returns False when sensor reading == 30°C."""
        mock_read.return_value = 30.0  # Exactly 30°C is NOT > 30
        self.assertFalse(alerts.too_hot("test_sensor"))
        mock_read.assert_called_once_with("test_sensor")

    @patch('alerts.read')
    def test_returns_false_when_warm_reading_below_threshold(self, mock_read):
        """Test that too_hot returns False when sensor reading < 30°C."""
        mock_read.return_value = 20.0  # 20 degrees Celsius is < 30
        self.assertFalse(alerts.too_hot("test_sensor"))
        mock_read.assert_called_once_with("test_sensor")

