        """Test that too_hot returns False for very low readings."""
        mock_read.return_value = 0.0  # 0 degrees Celsius is < 30
        self.assertFalse(alerts.too_hot("test_sensor"))
        mock_read.assert_called_once_with("test_sensor")

    @patch('alerts.read')
    def test_returns_false_for_negative_reading(self, mock_read):
        """Test that too_hot returns False for negative readings."""
        mock_read.return_value = -10.0  # Negative reading is < 30
        self.assertFalse(alerts.too_hot("test_sensor"))
        mock_read.assert_called_once_with("test_sensor")

