import solution

def test_first_or_with_list():
    assert solution.first_or([1, 2, 3]) == 1
    assert solution.first_or([]) is None
    assert solution.first_or([], 42) == 42

def test_first_or_with_tuple():
    assert solution.first_or((1, 2, 3)) == 1
    assert solution.first_or(()) is None
    assert solution.first_or((), "default") == "default"

def test_first_or_with_set():
    # Sets are unordered, but we just need the first element
    result = solution.first_or({1, 2, 3})
    assert result in {1, 2, 3}
    assert solution.first_or(set()) is None
    assert solution.first_or(set(), "default") == "default"

def test_first_or_with_generator():
    def gen():
        yield 1
        yield 2
    assert solution.first_or(gen()) == 1
    assert solution.first_or(iter([])) is None
    assert solution.first_or(iter([]), "default") == "default"

def test_first_or_with_string():
    assert solution.first_or("abc") == "a"
    assert solution.first_or("") is None
    assert solution.first_or("", "default") == "default"

def test_first_or_with_none_default():
    assert solution.first_or([]) is None
    assert solution.first_or([], None) is None

def test_first_or_with_complex_default():
    assert solution.first_or([], {"key": "value"}) == {"key": "value"}

