import sys
sys.path.insert(0, '.')

from solution import first_or

def test_list():
    assert first_or([1, 2, 3]) == 1
    assert first_or([]) is None
    assert first_or([]) == None

def test_set():
    # Sets are unordered, so we just check that it returns the first element
    # without raising an error. We can't predict which element, but we can
    # check it's one of them.
    result = first_or({1, 2, 3})
    assert result in {1, 2, 3}
    assert first_or(set()) is None

def test_generator():
    def gen():
        yield 1
        yield 2
    assert first_or(gen()) == 1

    def empty_gen():
        return
        yield
    assert first_or(empty_gen()) is None

def test_string():
    assert first_or("abc") == "a"
    assert first_or("") is None

def test_tuple():
    assert first_or((1, 2, 3)) == 1
    assert first_or(()) is None

def test_default():
    assert first_or([], "default") == "default"
    assert first_or([1], "default") == 1
    assert first_or([], "default") == "default"
    assert first_or([], "default") == "default"

def test_empty_generator_with_default():
    def empty_gen():
        return
        yield
    assert first_or(empty_gen(), "fallback") == "fallback"

def test_non_empty_generator_with_default():
    def gen():
        yield 1
    assert first_or(gen(), "fallback") == 1

