    """'1.2.3' -> (1, 2, 3)"""
    # Handle None, empty string, or non-string types
    if text is None or not isinstance(text, str):
        return None

    # Strip surrounding spaces
    text = text.strip()

    # Handle empty string after stripping
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v'):
        text = text[1:]

    # If the string is empty after removing 'v'
    if not text:
        return None

    # Split by '.'
    parts = text.split('.')

    # Check for valid parts: each part must be a digit string and we expect up to 3 parts
    # If more than 3 parts, it's malformed (e.g., '1.2.3.4')
    if len(parts) > 3:
        return None

    # Parse each part and validate it's an integer (no decimals, no letters)
    parsed_parts = []
    for part in parts:
        try:
            parsed_parts.append(int(part))
        except ValueError:
            return None

    # Pad to 3 if less than 3 parts (e.g., 'v1.2' -> (1, 2, 0), '2' -> (2, 0, 0))
    while len(parsed_parts) < 3:
        parsed_parts.append(0)

    return tuple(parsed_parts[:3])
