def read_config(path):
    """Return meaningful lines of a config file.

    Strips surrounding whitespace, skips blank lines and lines whose first
    non-space character is '#'. Returns [] if the file is missing.
    """
    try:
        with open(path, encoding="utf-8") as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        return []

    meaningful = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        meaningful.append(stripped)
    return meaningful

