import os
import uploads


def test_refuse_traversal():
    """Test that names with '..' are refused."""
    try:
        uploads.user_file('/base', '../x')
        assert False, "Expected ValueError for '../x'"
    except ValueError:
        pass


def test_refuse_deep_traversal():
    """Test that names with deep '..' sequences are refused."""
    try:
        uploads.user_file('/base', 'sub/../../x')
        assert False, "Expected ValueError for 'sub/../../x'"
    except ValueError:
        pass


def test_refuse_absolute_paths():
    """Test that absolute paths are refused."""
    try:
        uploads.user_file('/base', '/absolute/path')
        assert False, "Expected ValueError for '/absolute/path'"
    except ValueError:
        pass


def test_allow_simple_name():
    """Test that simple names are allowed and normalized."""
    result = uploads.user_file('/base', 'file.txt')
    assert result == '/base/file.txt'


def test_allow_nested_name():
    """Test that nested names without traversal are allowed."""
    result = uploads.user_file('/base', 'sub/file.txt')
    assert result == '/base/sub/file.txt'


def test_normalize_trailing_slash():
    """Test that trailing slashes are handled correctly."""
    result = uploads.user_file('/base/', 'file.txt')
    assert result == '/base/file.txt'


def test_normalize_double_slash():
    """Test that double slashes are normalized."""
    result = uploads.user_file('/base//', 'file.txt')
    assert result == '/base/file.txt'


def test_refuse_empty_name():
    """Test that empty names are refused (edge case)."""
    try:
        uploads.user_file('/base', '')
        assert False, "Expected ValueError for empty name"
    except ValueError:
        pass

