import os


def user_file(base, name):
    """Path of the uploaded file `name` inside the folder `base`."""
    # Normalize both paths to resolve '..' and other relative path tricks
    base_real = os.path.realpath(base)
    name_real = os.path.realpath(os.path.join(base, name))

    # Check if the resolved name is inside base
    # Ensure base ends with separator to prevent prefix matching issues like /foo vs /foobar
    if not base_real.endswith(os.sep):
        base_prefix = base_real + os.sep
    else:
        base_prefix = base_real

    if not name_real.startswith(base_prefix) and name_real != base_real:
        raise ValueError("Path escapes base directory")

    return os.path.join(base, name)

