import os


def find_ext(root, ext):
    """Files under root with the given extension, e.g. find_ext("src", ".py").

    Searches recursively and returns the matching files' paths relative to root,
    with '/' as the separator, sorted.
    """
    result = []
    for dirpath, _, filenames in os.walk(root):
        for filename in filenames:
            if filename.endswith(ext):
                # Calculate relative path from root
                rel_path = os.path.relpath(dirpath, root)
                if rel_path == '.':
                    # File is directly in root
                    full_rel = filename
                else:
                    full_rel = rel_path + '/' + filename
                result.append(full_rel)

    return sorted(result)
