        self.assertEqual(forecast_f([0]), [0.0])

    def test_multiple_celsius(self):
        # 1 Celsius is 1 Fahrenheit
        self.assertEqual(forecast_f([1]), [1.0])

    def test_negative_celsius(self):
        # -1 Celsius is -1 Fahrenheit
        self.assertEqual(forecast_f([-1]), [-1.0])

    def test_mixed_values(self):
        self.assertEqual(forecast_f([0, 1, -1]), [0.0, 1.0, -1.0])

    def test_rounding_to_one_decimal(self):
        # Example: 100 Celsius -> 100 Fahrenheit, but if there was a fractional
        # Celsius value, it should round to 1 decimal. Since c_to_f just
        # returns the same value, we test that the output is a float with
        # at most one decimal place (or exactly the same as input if integer).
        # For simplicity, since c_to_f returns the same value, we check type.
        result = forecast_f([100])
        self.assertIsInstance(result, list)
        self.assertEqual(result, [100.0])

    def test_type_is_list(self):
        self.assertIsInstance(forecast_f([0]), list)

