import unittest
from solution import word_count, unique_words


class TestSolution(unittest.TestCase):
    def test_word_count_empty(self):
        self.assertEqual(word_count(""), 0)

    def test_word_count_single_word(self):
        self.assertEqual(word_count("hello"), 1)

    def test_word_count_multiple_words(self):
        self.assertEqual(word_count("hello world"), 2)

    def test_word_count_multiple_words_with_spaces(self):
        self.assertEqual(word_count("  hello   world  "), 2)

    def test_unique_words_empty(self):
        self.assertEqual(unique_words(""), [])

    def test_unique_words_single_word(self):
        self.assertEqual(unique_words("hello"), ["hello"])

    def test_unique_words_duplicate_words(self):
        self.assertEqual(unique_words("hello hello world"), ["hello", "world"])

    def test_unique_words_case_sensitivity(self):
        self.assertEqual(sorted(unique_words("Hello hello HELLO")), ["HELLO", "Hello", "hello"])


if __name__ == '__main__':
    unittest.main()

