class TestUniqueWords(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(unique_words(""), [])

    def test_single_word(self):
        self.assertEqual(unique_words("hello"), ["hello"])

    def test_multiple_words(self):
        self.assertEqual(unique_words("hello world"), ["hello", "world"])

    def test_duplicate_words(self):
        self.assertEqual(sorted(unique_words("hello hello")), ["hello"])

    def test_case_sensitive(self):
        result = unique_words("Hello hello")
        self.assertIn("Hello", result)
        self.assertIn("hello", result)
        self.assertEqual(len(result), 2)

    def test_with_spaces(self):
        result = unique_words("  hello   world  ")
        self.assertEqual(result, ["hello", "world"])

    def test_with_newlines(self):
        result = unique_words("hello\nworld")
        self.assertEqual(result, ["hello", "world"])

    def test_with_punctuation(self):
        result = unique_words("hello,world!")
        self.assertIn("hello", result)
        self.assertIn("world", result)

    def test_mixed_case_duplicates(self):
        result = unique_words("Hello hello HELLO")
        self.assertIn("Hello", result)
        self.assertIn("hello", result)
        self.assertIn("HELLO", result)
        self.assertEqual(len(result), 3)

